-- Who last edited a claim (through the claim form or the row's amount entry; NULL: never edited). Like its opener,
-- they may not settle or approve it.
ALTER TABLE claim ADD COLUMN edited_by VARCHAR(100);
EOF
python3 - <<'EOF'
p='src/main/java/net/officefloor/hq/app/claim/ClaimRepository.java'
s=open(p).read()
s=s.replace('''    /** Store an edit of the claim, releasing its editor lock. */
    public void update(Claim claim) {''','''    /** Store the user's edit of the claim, releasing its editor lock and recording them as its last editor. */
    public void update(Claim claim, String user) {''')
s=s.replace('''tags = ?, locked_by = NULL WHERE sheet_id = ? AND id = ?",
                claim.amount(), claim.date(), claim.note(), claim.corrects(), claim.ref(), claim.tags(), claim.sheetId(), claim.id());''','''tags = ?, locked_by = NULL, edited_by = ? WHERE sheet_id = ? AND id = ?",
                claim.amount(), claim.date(), claim.note(), claim.corrects(), claim.ref(), claim.tags(), user, claim.sheetId(), claim.id());''')
s=s.replace('''    /** Who holds the claim's editor locked''','''    /** Who last edited the claim, or null when no one has. */
    public String editedBy(Claim claim) {
        return jdbc.query("SELECT edited_by FROM claim WHERE sheet_id = ? AND id = ?",
                rs -> rs.next() ? rs.getString(1) : null, claim.sheetId(), claim.id());
    }

    /** Who holds the claim's editor locked''')
open(p,'w').write(s)
p='src/main/java/net/officefloor/hq/app/claim/SaveClaim.java'
s=open(p).read()
s=s.replace('repository.update(claim);','repository.update(claim, input.user());')
open(p,'w').write(s)
p='src/main/java/net/officefloor/hq/app/claim/ClaimStatusChange.java'
s=open(p).read()
s=s.replace('''                throw new ClaimStatusNotAllowedException("The user who opened a claim cannot approve it.");
            }''','''                throw new ClaimStatusNotAllowedException("The user who opened a claim cannot approve it.");
            }
            if (input.action().equals("approve") && input.user().equals(repository.editedBy(loaded))) {
                throw new ClaimStatusNotAllowedException("The user who last edited a claim cannot approve it.");
            }''')
s=s.replace('''            throw new ClaimStatusNotAllowedException("The user who opened a claim cannot settle it.");
        }''','''            throw new ClaimStatusNotAllowedException("The user who opened a claim cannot settle it.");
        }
        if (input.action().equals("settle") && input.user().equals(repository.editedBy(loaded))) {
            throw new ClaimStatusNotAllowedException("The user who last edited a claim cannot settle it.");
        }''')
open(p,'w').write(s)
EOF
