package net.officefloor.hq.app.sheet;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;

/** The as-of date a screen reads the sheet as of (?asOf=yyyy-mm-dd): the sheet as it stood at the end of that day,
 *  every change made while the sheet's today was on or before it counting and every later one not, the date standing
 *  in for the sheet's today. */
public final class AsOf {

    private AsOf() {
    }

    /** The as-of date given (null: blank or not a date, the sheet as it is now). */
    public static LocalDate parse(String raw) {
        if (raw == null || raw.isBlank()) {
            return null;
        }
        try {
            return LocalDate.parse(raw.trim());
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's people, in the order they were added (as they stood at the end of the as-of date, when one is given). */
public class RespondWithPeople {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(name = "asOf", required = false) String asOf, PersonRepository repository,
            ObjectResponse<List<PersonResponse>> response) {
        String id = sheetId.trim();
        LocalDate end = AsOf.parse(asOf);
        List<Person> people = end != null ? repository.listAsOf(id, end) : repository.list(id);
        response.send(people.stream().map(PersonResponse::from).toList());
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** Every person's patrons on the sheet. */
public class RespondWithPatrons {
    public void respond(@PathVariable("sheetId") String sheetId, PatronRepository repository,
            ObjectResponse<List<PatronResponse>> response) {
        response.send(repository.list(sheetId.trim()).stream().map(PatronResponse::from).toList());
    }
}
package net.officefloor.hq.app.patron;

import net.officefloor.plugin.variable.Val;

public class SavePatron {
    public void save(@Val Patron patron, PatronRepository repository) {
        repository.insert(patron);
    }
}
